/* VILLAGE DEPTH REV 288: gameplay Y is a ground-plane lane/depth coordinate. */
typedef struct{short x,y,z;}V3;static MATRIX cam;static int ready=0;
static int shade(int v){return v<0?0:(v>255?255:v);}
static int wx(int sx){return (sx-160)*4;}
static int wz(int sy){return 980+(190-sy)*7;}
static void tri3(uint32_t*ot,char**pk,int d,V3 a,V3 b,V3 c,int r,int g,int bl){POLY_F3*p=(POLY_F3*)*pk;SVECTOR va={a.x,a.y,a.z,0},vb={b.x,b.y,b.z,0},vc={c.x,c.y,c.z,0};int32_t s0,s1,s2,flag;setPolyF3(p);setRGB0(p,r,g,bl);gte_ldv3(&va,&vb,&vc);gte_rtpt();gte_stsxy0(&s0);gte_stsxy1(&s1);gte_stsxy2(&s2);gte_stflg(&flag);if(!(flag&0x80000000)){setXY3(p,(short)s0,(short)(s0>>16),(short)s1,(short)(s1>>16),(short)s2,(short)(s2>>16));addPrim(ot+d,p);*pk+=sizeof(POLY_F3);}}
static void quad(uint32_t*ot,char**pk,int d,V3 a,V3 b,V3 c,V3 e,int r,int g,int bl){POLY_F4*p=(POLY_F4*)*pk;SVECTOR va={a.x,a.y,a.z,0},vb={b.x,b.y,b.z,0},vc={c.x,c.y,c.z,0},ve={e.x,e.y,e.z,0};int32_t s0,s1,s2,s3,flag;setPolyF4(p);setRGB0(p,r,g,bl);gte_ldv3(&va,&vb,&vc);gte_rtpt();gte_stsxy0(&s0);gte_stsxy1(&s1);gte_stsxy2(&s2);gte_ldv0(&ve);gte_rtps();gte_stsxy(&s3);gte_stflg(&flag);if(!(flag&0x80000000)){setXY4(p,(short)s0,(short)(s0>>16),(short)s1,(short)(s1>>16),(short)s2,(short)(s2>>16),(short)s3,(short)(s3>>16));addPrim(ot+d,p);*pk+=sizeof(POLY_F4);}}
static void box(uint32_t*ot,char**pk,int x,int y,int z,int w,int h,int dep,int r,int g,int b){V3 a={x,y,z},bb={x+w,y,z},c={x+w,y+h,z},d={x,y+h,z},e={x,y,z+dep},f={x+w,y,z+dep},gg={x+w,y+h,z+dep},hh={x,y+h,z+dep};quad(ot,pk,4,a,bb,c,d,r,g,b);quad(ot,pk,4,e,hh,gg,f,shade(r-16),shade(g-16),shade(b-16));quad(ot,pk,3,a,e,f,bb,shade(r+12),shade(g+12),shade(b+12));quad(ot,pk,3,d,c,gg,hh,shade(r-24),shade(g-24),shade(b-24));quad(ot,pk,3,a,d,hh,e,shade(r-10),shade(g-10),shade(b-10));quad(ot,pk,3,bb,f,gg,c,shade(r-5),shade(g-5),shade(b-5));}
void world3d_init(void){VECTOR t={0,0,0,0};SVECTOR rot={0,0,0,0};InitGeom();RotMatrix(&rot,&cam);TransMatrix(&cam,&t);gte_SetGeomOffset(160,112);gte_SetGeomScreen(210);ready=1;}
static void roof(uint32_t*ot,char**pk,int x,int y,int z,int w,int dep,int r,int g,int b){tri3(ot,pk,3,(V3){x,y,z},(V3){x+w/2,y-85,z+dep/2},(V3){x+w,y,z},r,g,b);tri3(ot,pk,3,(V3){x,y,z+dep},(V3){x+w,y,z+dep},(V3){x+w/2,y-85,z+dep/2},shade(r-18),shade(g-18),shade(b-18));}
static void house(uint32_t*ot,char**pk,int x,int z,int w,int h,int r,int g,int b){box(ot,pk,x,20,z,w,h,180,r,g,b);roof(ot,pk,x,20,z,w,180,112,58,104);box(ot,pk,x+w/2-28,20+h-72,z-8,56,72,18,72,43,35);box(ot,pk,x+22,55,z-10,42,42,16,65,128,148);box(ot,pk,x+w-64,55,z-10,42,42,16,65,128,148);}
static void tree(uint32_t*ot,char**pk,int x,int z){box(ot,pk,x-12,75,z,24,105,28,73,50,35);tri3(ot,pk,3,(V3){x-70,92,z},(V3){x,0,z+10},(V3){x+70,92,z},47,104,78);tri3(ot,pk,3,(V3){x-58,55,z+15},(V3){x,-28,z+20},(V3){x+58,55,z+15},55,125,91);}
static void shadow3(uint32_t*ot,char**pk,int x,int z,int w){quad(ot,pk,6,(V3){x-w,184,z-18},(V3){x+w,184,z-18},(V3){x+w-5,184,z+18},(V3){x-w+5,184,z+18},26,24,31);}
static void mote(uint32_t*ot,char**pk,int x,int y,int z,int tick){int p=10+((tick/5)&3);tri3(ot,pk,1,(V3){x,y-p,z},(V3){x+p,y,z},(V3){x,y+p,z},91,215,235);tri3(ot,pk,1,(V3){x,y-p,z},(V3){x,y+p,z},(V3){x-p,y,z},174,94,222);box(ot,pk,x-3,y-3,z-4,6,6,8,241,222,130);}
static void villager(uint32_t*ot,char**pk,int x,int z,int tick,int active){int bob=((tick/18)&1)*3;shadow3(ot,pk,x,z,24);box(ot,pk,x-18,102-bob,z,36,66,34,66,105,130);box(ot,pk,x-22,68-bob,z-2,44,38,38,188,157,125);tri3(ot,pk,2,(V3){x-22,70-bob,z},(V3){x,42-bob,z+6},(V3){x+22,70-bob,z},67,48,83);box(ot,pk,x-24,165-bob,z,18,20,28,49,45,55);box(ot,pk,x+6,165-bob,z,18,20,28,49,45,55);if(active){int p=5+((tick/8)&3);tri3(ot,pk,1,(V3){x,42-p,z-8},(V3){x+p,48,z-8},(V3){x,54+p,z-8},232,198,89);tri3(ot,pk,1,(V3){x,42-p,z-8},(V3){x,54+p,z-8},(V3){x-p,48,z-8},114,215,224);}}
static void enemy(uint32_t*ot,char**pk,int x,int z,int hp,int tick){int bob=((tick/7)&1)*5;if(hp<=0)return;shadow3(ot,pk,x,z,40);box(ot,pk,x-35,105-bob,z,70,58,50,72,35,96);tri3(ot,pk,2,(V3){x-35,108-bob,z},(V3){x-19,67-bob,z+8},(V3){x-5,109-bob,z},126,56,130);tri3(ot,pk,2,(V3){x+5,109-bob,z},(V3){x+19,67-bob,z+8},(V3){x+35,108-bob,z},126,56,130);box(ot,pk,x-22,124-bob,z-7,12,8,8,235,197,80);box(ot,pk,x+10,124-bob,z-7,12,8,8,235,197,80);box(ot,pk,x-29,160-bob,z,22,24,34,42,27,60);box(ot,pk,x+7,160-bob,z,22,24,34,42,27,60);}
static void moko3d(uint32_t*ot,char**pk,int mx,int ground_y,int mz,int facing,int tick,int jump){int bob=((tick/8)&1)*3,dir=facing?1:-1;int y=ground_y-jump;int sw=34-(jump>35?10:jump/4);if(sw<18)sw=18;shadow3(ot,pk,mx,mz,sw);box(ot,pk,mx-28,y+72-bob,mz,56,65,48,101,54,151);box(ot,pk,mx-38,y+28-bob,mz-2,76,52,52,139,79,184);tri3(ot,pk,2,(V3){mx-34,y+35-bob,mz},(V3){mx-18,y-10-bob,mz+6},(V3){mx-4,y+34-bob,mz},103,45,145);tri3(ot,pk,2,(V3){mx+4,y+34-bob,mz},(V3){mx+18,y-10-bob,mz+6},(V3){mx+34,y+35-bob,mz},103,45,145);box(ot,pk,mx-19,y+52-bob,mz-10,38,18,18,211,184,201);box(ot,pk,mx-20,y+139-bob,mz,18,38,34,70,35,111);box(ot,pk,mx+2,y+139-bob,mz,18,38,34,70,35,111);box(ot,pk,mx-24,y+174-bob,mz-4,23,13,40,48,27,78);box(ot,pk,mx+1,y+174-bob,mz-4,23,13,40,48,27,78);box(ot,pk,mx-15,y+96-bob,mz-9,30,30,12,205,166,76);box(ot,pk,mx-8,y+103-bob,mz-14,16,16,8,238,220,154);box(ot,pk,mx-2,y+106-bob,mz-17,4,12,5,32,28,40);if(dir>0){box(ot,pk,mx+28,y+114-bob,mz+18,32,7,8,209,61,137);box(ot,pk,mx+56,y+78-bob,mz+18,7,43,8,209,61,137);}else{box(ot,pk,mx-60,y+114-bob,mz+18,32,7,8,209,61,137);box(ot,pk,mx-63,y+78-bob,mz+18,7,43,8,209,61,137);}}
void world3d_draw_village(int px,int py,int player_jump,int facing,int tick,int motes,int enemy_hp,int clear,uint32_t*ot,char**pk){int i;VECTOR t;int camx=(px-145)*4,mx=wx(px),mz=wz(py);if(!ready)world3d_init();t.vx=-camx;t.vy=-54;t.vz=0;TransMatrix(&cam,&t);gte_SetRotMatrix(&cam);gte_SetTransMatrix(&cam);quad(ot,pk,7,(V3){-1200,188,520},(V3){1200,188,520},(V3){1200,188,1850},(V3){-1200,188,1850},76,72,62);quad(ot,pk,7,(V3){-1200,-420,1840},(V3){1200,-420,1840},(V3){1200,188,1840},(V3){-1200,188,1840},68,83,103);for(i=0;i<10;i++){int x=-1150+i*255;box(ot,pk,x,181,650+(i&1)*80,170,7,720,104,93,72);}house(ot,pk,-980,1510,300,260,111,96,88);house(ot,pk,-570,1460,340,300,128,106,89);house(ot,pk,400,1470,350,285,117,91,83);house(ot,pk,840,1510,310,250,130,103,88);tree(ot,pk,-740,1270);tree(ot,pk,170,1310);tree(ot,pk,770,1260);box(ot,pk,-150,120,1260,300,18,420,101,91,68);box(ot,pk,830,92,1210,220,22,360,103,91,66);villager(ot,pk,wx(278),wz(174),tick,(motes>0&&motes<3));if(motes<1)mote(ot,pk,wx(185),92,wz(176),tick);if(motes<2)mote(ot,pk,wx(348),82,wz(153),tick+12);if(motes<3)mote(ot,pk,wx(452),76,wz(141),tick+24);enemy(ot,pk,wx(503),wz(176),enemy_hp,tick);if(clear){box(ot,pk,wx(600),38,1250,36,150,40,50,136,88);box(ot,pk,wx(615),38,1250,36,150,40,50,136,88);tri3(ot,pk,2,(V3){wx(598),40,1240},(V3){wx(625),40,1240},(V3){wx(611),-35,1260},88,168,118);}else{box(ot,pk,wx(600),38,1250,36,150,40,92,49,63);box(ot,pk,wx(615),38,1250,36,150,40,92,49,63);}moko3d(ot,pk,mx,0,mz,facing,tick,player_jump);}
void world3d_draw_station(int px,int py,int facing,int tick,uint32_t*ot,char**pk){world3d_draw_village(px,py,0,facing,tick,3,0,1,ot,pk);}
